"use strict";(self.webpackChunknautilus_trader_doc=self.webpackChunknautilus_trader_doc||[]).push([["3103"],{33054(e,n,t){t.r(n),t.d(n,{metadata:()=>r,default:()=>m,frontMatter:()=>o,contentTitle:()=>s,toc:()=>l,assets:()=>d});var r=JSON.parse('{"id":"tutorials/orderbook_data","title":"\u8BA2\u5355\u7C3F\u6570\u636E","description":"order-book-data}","source":"@site/docs/tutorials/orderbook_data.md","sourceDirName":"tutorials","slug":"/tutorials/orderbook_data","permalink":"/tutorials/orderbook_data","draft":false,"unlisted":false,"editUrl":"https://github.com/Aloento/NautilusTraderDoc/tree/main/docs/tutorials/orderbook_data.md","tags":[],"version":"current","lastUpdatedAt":1792017030000,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"\u671F\u6743\u6570\u636E\u4E0E Greeks\uFF08Bybit\uFF09","permalink":"/tutorials/options_data_bybit"},"next":{"title":"\u8BA2\u5355\u7C3F\u5931\u8861","permalink":"/tutorials/orderbook_imbalance"}}'),i=t(47259),a=t(29087);let o={},s="\u8BA2\u5355\u7C3F\u6570\u636E {#order-book-data}",d={},l=[];function c(e){let n={code:"code",h1:"h1",header:"header",p:"p",pre:"pre",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"order-book-data",children:"\u8BA2\u5355\u7C3F\u6570\u636E"})}),"\n",(0,i.jsx)(n.p,{children:"\u52A0\u8F7D Bybit \u8BA2\u5355\u7C3F\u5F52\u6863\uFF0C\u628A\u4EA4\u6613\u573A\u6240\u7684\u89C4\u8303\u5316\u6570\u636E\u884C\u8F6C\u6362\u4E3A NautilusTrader \u8BA2\u5355\u7C3F\u589E\u91CF\uFF08order book deltas\uFF09\uFF0C\u4F9B Binance \u548C Bybit \u56DE\u6D4B\u6559\u7A0B\u4F7F\u7528\u3002"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'from __future__ import annotations\n\nimport json\nimport tempfile\nfrom collections.abc import Iterable\nfrom collections.abc import Iterator\nfrom decimal import Decimal\nfrom os import PathLike\nfrom pathlib import Path\nfrom zipfile import ZipFile, is_zipfile\n\nimport pandas as pd\nfrom nautilus_trader import __version__\nfrom nautilus_trader.model import (\n    BookAction,\n    BookOrder,\n    CryptoPerpetual,\n    CurrencyPair,\n    OrderBookDelta,\n    OrderSide,\n    Price,\n    Quantity,\n    RecordFlag,\n)\nfrom nautilus_trader.testkit.providers import TEST_DATA_DIR, TestDataProvider\n\n\ndef sample_data_path(name: str) -> Path:\n    """\n    Return a local path for the bundled sample file at the given relative `name`.\n\n    Reads from the `test_data/` directory in a source checkout, and downloads to a\n    temporary directory otherwise, so the loaders that only accept a file path work from\n    an installed wheel. Downloads are cached per installed NautilusTrader version.\n\n    """\n    local = TEST_DATA_DIR / name\n    if local.is_file():\n        return local\n\n    cached = Path(tempfile.gettempdir()) / "nautilus_sample_data" / __version__ / name\n    if not cached.is_file():\n        cached.parent.mkdir(parents=True, exist_ok=True)\n        cached.write_bytes(TestDataProvider().read(name))\n\n    return cached\n\n\ndef deltas_from_frame(\n    frame: pd.DataFrame,\n    instrument: CurrencyPair | CryptoPerpetual,\n) -> list[OrderBookDelta]:\n    """\n    Convert loader rows and preserve snapshot and event boundaries.\n    """\n    if frame.empty:\n        return []\n\n    instrument_id = str(instrument.id)\n    if not frame["instrument_id"].eq(instrument_id).all():\n        raise ValueError(f"Expected only {instrument_id} order book data")\n\n    rows = list(frame.itertuples())\n    deltas: list[OrderBookDelta] = []\n    first = rows[0]\n    first_action = BookAction.from_str(first.action)\n    if int(first.flags) & RecordFlag.F_SNAPSHOT.value and first_action != BookAction.CLEAR:\n        ts = int(first.Index.value)\n        deltas.append(\n            OrderBookDelta(\n                instrument_id=instrument.id,\n                action=BookAction.CLEAR,\n                order=BookOrder(\n                    side=OrderSide.from_str(first.side),\n                    price=Price.from_decimal_dp(\n                        Decimal(str(first.price)),\n                        instrument.price_precision,\n                    ),\n                    size=Quantity.zero(instrument.size_precision),\n                    order_id=0,\n                ),\n                flags=RecordFlag.F_SNAPSHOT.value,\n                sequence=int(first.sequence),\n                ts_event=ts,\n                ts_init=ts,\n            ),\n        )\n\n    for index, row in enumerate(rows):\n        ts = int(row.Index.value)\n        next_row = rows[index + 1] if index + 1 < len(rows) else None\n        flags = int(row.flags)\n        next_starts_snapshot = next_row is not None and next_row.action == "CLEAR"\n        snapshot_continues = (\n            next_row is not None\n            and not next_starts_snapshot\n            and flags & RecordFlag.F_SNAPSHOT.value\n            and int(next_row.flags) & RecordFlag.F_SNAPSHOT.value\n        )\n        event_continues = (\n            next_row is not None\n            and not next_starts_snapshot\n            and next_row.Index == row.Index\n            and next_row.sequence == row.sequence\n        )\n\n        if not snapshot_continues and not event_continues:\n            flags |= RecordFlag.F_LAST.value\n        deltas.append(\n            OrderBookDelta(\n                instrument_id=instrument.id,\n                action=BookAction.from_str(row.action),\n                order=BookOrder(\n                    side=OrderSide.from_str(row.side),\n                    price=Price.from_decimal_dp(\n                        Decimal(str(row.price)),\n                        instrument.price_precision,\n                    ),\n                    size=Quantity.from_decimal_dp(\n                        Decimal(str(row.size)),\n                        instrument.size_precision,\n                    ),\n                    order_id=int(row.order_id),\n                ),\n                flags=flags,\n                sequence=int(row.sequence),\n                ts_event=ts,\n                ts_init=ts,\n            ),\n        )\n    return deltas\n\n\ndef load_bybit_order_book_deltas(\n    file_path: str | PathLike[str],\n    nrows: int | None = None,\n) -> pd.DataFrame:\n    if not is_zipfile(file_path):\n        raise ValueError("Bybit order book data must be a ZIP archive")\n\n    rows = []\n    with ZipFile(file_path) as archive, archive.open(archive.namelist()[0]) as file:\n        for event in _bybit_events(file):\n            if nrows is not None and len(rows) + len(event) > nrows:\n                break\n            rows.extend(event)\n\n    columns = [\n        "timestamp",\n        "instrument_id",\n        "action",\n        "side",\n        "price",\n        "size",\n        "order_id",\n        "flags",\n        "sequence",\n    ]\n    frame = pd.DataFrame(rows, columns=columns).set_index("timestamp")\n    return frame.astype({"order_id": int, "flags": int, "sequence": int})\n\n\ndef _bybit_events(lines: Iterable[bytes]) -> Iterator[list[dict[str, object]]]:\n    for line in lines:\n        message = json.loads(line)\n        data = message["data"]\n        timestamp = pd.to_datetime(int(message["ts"]) * 1_000_000, unit="ns", utc=True)\n        snapshot = message["type"] == "snapshot"\n        sides = [(side, data.get(key) or []) for key, side in (("b", "BUY"), ("a", "SELL"))]\n        event = []\n\n        if snapshot:\n            side, levels = next(((side, levels) for side, levels in sides if levels), ("BUY", []))\n            event.append(\n                {\n                    "timestamp": timestamp,\n                    "instrument_id": f"{data[\'s\']}-LINEAR.BYBIT",\n                    "action": "CLEAR",\n                    "side": side,\n                    "price": levels[0][0] if levels else "0",\n                    "size": "0",\n                    "order_id": 0,\n                    "flags": RecordFlag.F_SNAPSHOT.value,\n                    "sequence": data["seq"],\n                },\n            )\n\n        for side, levels in sides:\n            for price, size in levels:\n                if snapshot:\n                    action = "ADD"\n                elif Decimal(size) == 0:\n                    action = "DELETE"\n                else:\n                    action = "UPDATE"\n\n                event.append(\n                    {\n                        "timestamp": timestamp,\n                        "instrument_id": f"{data[\'s\']}-LINEAR.BYBIT",\n                        "action": action,\n                        "side": side,\n                        "price": price,\n                        "size": size,\n                        "order_id": 0,\n                        "flags": RecordFlag.F_SNAPSHOT.value if snapshot else 0,\n                        "sequence": data["seq"],\n                    },\n                )\n\n        yield event\n'})})]})}function m(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},29087(e,n,t){t.d(n,{R:()=>o,x:()=>s});var r=t(96363);let i={},a=r.createContext(i);function o(e){let n=r.useContext(a);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),r.createElement(a.Provider,{value:n},e.children)}}}]);